<script lang="ts">
  import { onDestroy } from 'svelte';
  import { videoStore } from '$stores/video.svelte';
  let preview = $state<HTMLVideoElement>(); let canvas = $state<HTMLCanvasElement>();
  let stream: MediaStream | null = null; let recorder: MediaRecorder | null = null; let chunks: Blob[] = []; let interval: ReturnType<typeof setInterval> | null = null;
  let cameras = $state<MediaDeviceInfo[]>([]); let deviceId = $state(''); let facing = $state<'user' | 'environment'>('user'); let recording = $state(false); let paused = $state(false); let timer = $state(0); let mic = $state(true); let error = $state(''); let torch = $state(false); let zoom = $state(1); let exposure = $state(0); let resolution = $state('1280x720'); let fps = $state(30); let photoFlash = $state(false);
  onDestroy(() => { stopCamera(); });
  async function openCamera() {
    error = ''; stopCamera();
    const [width, height] = resolution.split('x').map(Number);
    try {
      stream = await navigator.mediaDevices.getUserMedia({ video: { deviceId: deviceId ? { exact: deviceId } : undefined, facingMode: deviceId ? undefined : { ideal: facing }, width: { ideal: width }, height: { ideal: height }, frameRate: { ideal: fps } }, audio: mic });
      if (preview) { preview.srcObject = stream; await preview.play(); }
      const devices = await navigator.mediaDevices.enumerateDevices(); cameras = devices.filter((device) => device.kind === 'videoinput');
      const track = stream.getVideoTracks()[0]; const settings = track?.getSettings(); if (settings?.deviceId) deviceId = settings.deviceId;
      applyVideoControls();
    } catch (reason) { error = reason instanceof Error ? reason.message : 'Camera permission was not granted.'; }
  }
  function stopCamera() { if (interval) clearInterval(interval); interval = null; recorder?.state !== 'inactive' && recorder?.stop(); stream?.getTracks().forEach((track) => track.stop()); stream = null; recorder = null; recording = false; paused = false; }
  async function switchFacing() { facing = facing === 'user' ? 'environment' : 'user'; deviceId = ''; await openCamera(); }
  async function applyVideoControls() { const track = stream?.getVideoTracks()[0] as (MediaStreamTrack & { applyConstraints: (constraints: MediaTrackConstraints) => Promise<void> }) | undefined; if (!track) return; try { await track.applyConstraints({ advanced: [{ zoom, exposureMode: 'continuous', exposureCompensation: exposure, torch } as MediaTrackConstraintSet] }); } catch { /* unsupported controls simply remain unavailable on this device */ } }
  function takePhoto() { if (!preview || !canvas) return; canvas.width = preview.videoWidth; canvas.height = preview.videoHeight; canvas.getContext('2d')?.drawImage(preview, 0, 0); if (photoFlash) { const context = canvas.getContext('2d'); if (context) { context.fillStyle = 'rgba(255,255,255,.2)'; context.fillRect(0,0,canvas.width,canvas.height); } } const link = document.createElement('a'); link.href = canvas.toDataURL('image/png'); link.download = `happy-study-photo-${Date.now()}.png`; link.click(); }
  function toggleRecording() { if (recording) { if (paused) { recorder?.resume(); paused = false; } else { recorder?.pause(); paused = true; } return; } if (!stream) { error = 'Open a camera before recording.'; return; } const mime = ['video/webm;codecs=vp9,opus','video/webm;codecs=vp8,opus','video/webm'].find((type) => MediaRecorder.isTypeSupported(type)); recorder = mime ? new MediaRecorder(stream, { mimeType: mime, videoBitsPerSecond: 4_000_000 }) : new MediaRecorder(stream); chunks = []; recorder.ondataavailable = (event) => { if (event.data.size) chunks.push(event.data); }; recorder.onstop = async () => { if (!chunks.length) return; await videoStore.add(new Blob(chunks, { type: recorder?.mimeType || 'video/webm' }), timer, `Camera recording ${new Date().toLocaleString()}`); chunks=[]; }; recorder.start(1000); recording = true; paused = false; timer = 0; interval = setInterval(() => { if (!paused) timer += 1; }, 1000); }
  function finishRecording() { if (recorder?.state !== 'inactive') recorder.stop(); if (interval) clearInterval(interval); interval = null; recording = false; paused = false; }
  function clock() { return `${Math.floor(timer/60)}:${String(timer%60).padStart(2,'0')}`; }
</script>

<svelte:head><title>Camera Studio · Happy Study</title><meta name="description" content="Capture photos and study demonstrations from your camera." /></svelte:head>

<div class="camera-app"><section class="top"><div><p class="eyebrow">CAMERA STUDIO</p><h1>Show the process.<br /><em>Teach the idea.</em></h1><p>Capture an engineering model, hand-drawn flowchart, coding explanation, or practical demonstration.</p></div><div class="record-state"><span class:live={recording}></span><small>{recording ? (paused ? 'PAUSED' : 'RECORDING') : 'CAMERA READY'}</small><strong>{clock()}</strong></div></section><section class="camera-layout"><div class="viewfinder"><video bind:this={preview} muted playsinline></video><canvas bind:this={canvas}></canvas>{#if photoFlash}<div class="gridlines"></div>{/if}<div class="viewfinder-hud"><span>{resolution} · {fps} FPS</span><span>{facing === 'user' ? 'FRONT' : 'REAR'}</span></div>{#if !stream}<button class="open" onclick={openCamera}>Open camera</button>{/if}</div><aside class="controls"><p class="eyebrow">CAPTURE CONTROLS</p><label>Camera<select bind:value={deviceId} onchange={openCamera}><option value="">Auto / {facing === 'user' ? 'front' : 'rear'}</option>{#each cameras as camera}<option value={camera.deviceId}>{camera.label || 'Camera'}</option>{/each}</select></label><div class="pair"><button onclick={switchFacing}>Switch front / rear</button><button class:active={torch} onclick={() => { torch = !torch; applyVideoControls(); }}>Torch</button></div><label>Resolution<select bind:value={resolution} onchange={openCamera}><option value="640x480">480p</option><option value="1280x720">720p</option><option value="1920x1080">1080p</option></select></label><label>Frame rate<select bind:value={fps} onchange={openCamera}><option value={24}>24 FPS</option><option value={30}>30 FPS</option><option value={60}>60 FPS</option></select></label><label class="slider">Digital zoom <output>{zoom.toFixed(1)}x</output><input type="range" min="1" max="4" step=".1" bind:value={zoom} oninput={applyVideoControls} /></label><label class="slider">Exposure <output>{exposure.toFixed(1)}</output><input type="range" min="-2" max="2" step=".1" bind:value={exposure} oninput={applyVideoControls} /></label><label class="check"><input type="checkbox" bind:checked={mic} /> Capture microphone audio</label><label class="check"><input type="checkbox" bind:checked={photoFlash} /> Grid overlay / photo flash</label><div class="actions"><button class="photo" onclick={takePhoto}>Take photo</button>{#if recording}<button onclick={toggleRecording}>{paused ? 'Resume' : 'Pause'}</button><button class="stop" onclick={finishRecording}>Stop video</button>{:else}<button class="record" onclick={toggleRecording}>Record video</button>{/if}</div></aside></section>{#if error}<p class="error">{error}</p>{/if}<section class="guide"><div><b>Photos</b><span>Saved as PNG files to your device.</span></div><div><b>Videos</b><span>Saved in the Screen Studio media bin after recording.</span></div><div><b>Device support</b><span>Torch, focus, zoom, and exposure appear where the camera/browser supports them.</span></div></section></div>

