nsparent 33.8%,transparent 66.2%,rgba(255,255,255,.28) 66.5%,transparent 66.8%)}.open{padding:.75rem 1rem;border:0;border-radius:10px;background:#22d3ee;color:#083344;font-weight:800;cursor:pointer}.controls{padding:1.15rem;background:#0a0f1d;display:grid;align-content:start;gap:.8rem}.controls label{display:grid;gap:.35rem;font-size:.72rem;letter-spacing:.07em;color:#94a3b8}.controls select{background:#111827;border:1px solid #334155;border-radius:8px;color:#e2e8f0;padding:.55rem}.pair,.actions{display:flex;gap:.5rem;flex-wrap:wrap}.pair button,.actions button{flex:1;border:1px solid rgba(148,163,184,.24);border-radius:8px;background:#172554;color:#e2e8f0;padding:.62rem;cursor:pointer;font-weight:700}.pair button.active{background:#f59e0b;color:#451a03}.slider output{float:right;color:#e0f2fe}.slider input{accent-color:#22d3ee}.check{display:flex!important;align-items:center;grid-template-columns:auto 1fr;gap:.5rem!important;letter-spacing:0!important}.actions .photo{background:#e0f2fe;color:#083344}.actions .record{background:#f43f5e;color:#fff}.actions .stop{background:#fb7185;color:#4c0519}.error{padding:.8rem;border-radius:10px;border:1px solid rgba(244,63,94,.35);background:rgba(190,24,93,.16);color:#fecdd3}.guide{display:grid;grid-template-columns:repeat(3,1fr);gap:.8rem}.guide div{padding:1rem;border:1px solid rgba(148,163,184,.15);border-radius:12px;background:rgba(30,41,59,.5)}.guide b{display:block;color:#a5f3fc}.guide span{color:#94a3b8;font-size:.78rem}@keyframes pulse{50%{transform:scale(.8);opacity:.65}}@media(max-width:850px){.camera-layout{grid-template-columns:1fr}.viewfinder{min-height:380px}.top{align-items:start;flex-direction:column}.guide{grid-template-columns:1fr}}
</style>
